// Pure helpers, safe for client and server.

// Only absolute https:// links are accepted for a work's live site (no javascript:, data:, http:, relative paths).
export function safeHttpsUrl(input: unknown): string | null {
  if (typeof input !== "string") return null
  const s = input.trim()
  if (!s || s.length > 500) return null
  try {
    const u = new URL(s)
    if (u.protocol !== "https:" || !u.hostname || u.username || u.password) return null
    return u.toString()
  } catch {
    return null
  }
}

// uploaded image names are always <uuid>.webp, generated by the server
export const IMAGE_NAME = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.webp$/

export function imageUrl(name: string) {
  return IMAGE_NAME.test(name) ? `/uploads/${name}` : ""
}
